import java.util.*;
import java.io.*;

public class e{

	static long mod = 998244353;

	public static void main(String[] args){
		JS scan = new JS();
		long n = scan.nextLong();
		long m = scan.nextLong();
		long L = scan.nextLong();
		long R = scan.nextLong();
		long h = R-L;

		long e = 0;
		long o = 0;
		if(h % 2 == 1){
			long d = (h+1)/2;
			e = d;
			o = d;
		}
		else{
			long d = h/2;
			e = d;
			o = d;
			if(L % 2 == 1) o++;
			else e++;
		}

		long[][] mat = {{e, o},{o, e}};
		long[][] pphard = pow(mat, m*n);
		long ans = pphard[0][0];
		if((n*m)%2==1) ans += pphard[0][1];
		System.out.println(ans%mod);
	}

	static long[][] pow(long[][] a, long pow){
		if(pow == 0) return iden(a.length);
		if(pow % 2 == 1){
			long[][] res = pow(a, pow-1);
			return mult(res, a);
		}
		long[][] res = pow(a, pow/2);
		return mult(res, res);
	}

	static long[][] iden(int n){
		long[][] res = new long[n][n];
		for(int i = 0; i < n; i++) res[i][i] = 1;
		return res;
	}

	static long[][] mult(long[][] a, long[][] b){
		long[][] res = new long[a.length][b[0].length];
		for(int i = 0; i < a.length; i++){
			for(int j = 0; j < b[0].length; j++){
				for(int k = 0; k < a[0].length; k++){
					res[i][j] += (a[i][k]%mod)*(b[k][j]%mod);
					res[i][j] %= mod;
				}
			}
		}
		return res;
	}

	static class JS{
		public int BS = 1<<16;
		public char NC = (char)0;
		byte[] buf = new byte[BS];
		int bId = 0, size = 0;
		char c = NC;
		double num = 1;
		BufferedInputStream in;

		public JS() {
			in = new BufferedInputStream(System.in, BS);
		}

		public JS(String s) throws FileNotFoundException {
			in = new BufferedInputStream(new FileInputStream(new File(s)), BS);
		}

		public char nextChar(){
			while(bId==size) {
				try {
					size = in.read(buf);
				}catch(Exception e) {
					return NC;
				}				
				if(size==-1)return NC;
				bId=0;
			}
			return (char)buf[bId++];
		}

		public int nextInt() {
			return (int)nextLong();
		}

		public long nextLong() {
			num=1;
			boolean neg = false;
			if(c==NC)c=nextChar();
			for(;(c<'0' || c>'9'); c = nextChar()) {
				if(c=='-')neg=true;
			}
			long res = 0;
			for(; c>='0' && c <='9'; c=nextChar()) {
				res = (res<<3)+(res<<1)+c-'0';
				num*=10;
			}
			return neg?-res:res;
		}

		public double nextDouble() {
			double cur = nextLong();
			return c!='.' ? cur:cur+nextLong()/num;
		}

		public String next() {
			StringBuilder res = new StringBuilder();
			while(c<=32)c=nextChar();
			while(c>32) {
				res.append(c);
				c=nextChar();
			}
			return res.toString();
		}

		public String nextLine() {
			StringBuilder res = new StringBuilder();
			while(c<=32)c=nextChar();
			while(c!='\n') {
				res.append(c);
				c=nextChar();
			}
			return res.toString();
		}

		public boolean hasNext() {
			if(c>32)return true;
			while(true) {
				c=nextChar();
				if(c==NC)return false;
				else if(c>32)return true;
			}
		}
	}

}
